<?php
declare(strict_types=1);ob_start();require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/super_app_v700.php';$id=(int)($_GET['id']??0);$h=v700_one('tourism_hotels_v700',$id,"status='active'");if(!$h){http_response_code(404);exit('Hotel not found.');}$rooms=v700_rows("SELECT * FROM tourism_hotel_rooms_v700 WHERE tenant_id=? AND hotel_id=? AND status='active' ORDER BY price_per_night",[v700_tid(),$id]);$u=v700_user();$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!$u){header('Location: '.v700_login_url($_SERVER['REQUEST_URI']??'/hotel.php?id='.$id));exit;}csrf_check();$_POST['hotel_id']=$id;$bid=v700_create_hotel_booking((int)$u['id'],$_POST);$flash='Booking request submitted. ID #'.$bid;}}catch(Throwable $e){$err=$e->getMessage();}v700_track('tourism','view','hotel',$id);v700_public_header($h['name'],strip_tags((string)($h['description']?:'Hotel booking on ShahkotPK')),'tourism');?>
<main><section class="v700-account-hero"><div class="v700-shell"><span class="v700-kicker">🏨 HOTEL <?=$h['verified']?'· VERIFIED':''?></span><h1><?=e($h['name'])?></h1><p><?=e($h['area']?:$h['address']?:'Local accommodation')?> · <?=e($h['star_rating']>0?($h['star_rating'].' ★'):'Guest stay')?></p></div></section><section class="v700-section soft"><div class="v700-shell"><div class="v700-grid" style="grid-template-columns:1.3fr .7fr"><section class="v700-panel"><h2>About this stay</h2><p><?=nl2br(e($h['description']?:'No description provided.'))?></p><h3>Rooms</h3><div class="v700-list"><?php foreach($rooms as $r):?><div class="v700-row"><i>🛏</i><span><b><?=e($r['name'])?></b><small><?=e($r['room_type']?:'Room')?> · Up to <?=number_format((int)$r['capacity'])?> guests</small></span><strong><?=v700_money((float)$r['price_per_night'])?>/night</strong></div><?php endforeach;?></div></section><aside class="v700-panel"><?php if($flash):?><div class="v700-alert success"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="v700-alert error"><?=e($err)?></div><?php endif;?><h2>Book a room</h2><form method="post" class="v700-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Room<select name="room_id" required><?php foreach($rooms as $r):?><option value="<?=(int)$r['id']?>"><?=e($r['name'])?> · <?=v700_money((float)$r['price_per_night'])?></option><?php endforeach;?></select></label><div class="two"><label>Check-in<input type="date" name="check_in" required></label><label>Check-out<input type="date" name="check_out" required></label></div><label>Guests<input type="number" name="guests" min="1" value="2"></label><div class="two"><label>Guest name<input name="guest_name" value="<?=e($u['name']??'')?>"></label><label>Phone<input name="guest_phone" value="<?=e($u['phone']??'')?>"></label></div><button class="v700-btn primary">Request Booking</button></form></aside></div></div></section></main><?php v700_public_footer(); ?>
